 S.transferEmployee=await userSession(S.system,{email:`test-transfer-employee-${run}@example.test`,name:`TEST Transfer Employee ${run}`});
 S.atsHr=await userSession(S.system,{email:`test-ats-hr-${run}@example.test`,name:`TEST ATS HR ${run}`});
 S.finance=await userSession(S.system,{email:`test-hrm-finance-${run}@example.test`,name:`TEST Finance ${run}`});
 for(const [user,role] of [[S.hrm,"hrm_admin"],[S.hr,"hrm_officer"],[S.manager,"people_manager"],[S.employeeA,"employee"],[S.employeeB,"employee"],[S.transferEmployee,"employee"],[S.atsHr,"hr"],[S.finance,"finance"]])assert.equal((await grant(user,role)).status,303);
 const browserQa=process.env.HRM_BROWSER_BINARY?await startHrmBrowserQa({baseUrl:BASE,binary:process.env.HRM_BROWSER_BINARY,artifactDir:process.env.HRM_BROWSER_ARTIFACT_DIR}):null;
 if(browserQa)t.after(()=>browserQa.close());
 const auditPair=async(user,name,enPath,viPath,enText,viText,formsRequired=true)=>{
  try{await browserQa.auditPage(user,enPath,{expectedText:enText,artifactName:`${name}-en`,formsRequired});}catch(error){throw new Error(`${name} EN (${enPath}) expected ${enText}: ${error instanceof Error?error.message:String(error)}`)}
  try{await browserQa.auditPage(user,viPath,{expectedText:viText,artifactName:`${name}-vi`,formsRequired});}catch(error){throw new Error(`${name} VI (${viPath}) expected ${viText}: ${error instanceof Error?error.message:String(error)}`)}
 };
 assert.equal((await S.finance.get("/hrm")).status,403,"CRM Finance is not HRM access");
 assert.equal((await S.hr.get("/workspace/users")).status,403,"HRM Officer cannot manage accounts");
 const closed=await S.employeeA.get("/hrm");assert.equal(closed.status,503,"Closed HRM gate response: " + closed.html);
 assert.equal((await S.hrm.get("/hrm/settings")).status,200,"HRM Admin can configure while the employee module remains unavailable");
 const configured=await S.hrm.post("/hrm/settings",{request_key:"hrm_policy_"+run,version:1,legal_entity:"TEST Local entity",purpose:"Synthetic test only",retention_policy:"Synthetic records deleted with test state",policy_reference:"TEST-only synthetic policy",reviewed:"1",enabled:"1"});assert.equal(configured.status,303,configured.html);
 const retentionSetup=await S.hrm.get("/hrm/retention");assert.equal(retentionSetup.status,200);assert.ok(retentionSetup.html.includes("retention_days")&&retentionSetup.html.includes("null"),"the policy editor starts with empty, unscheduled durations");assert.equal(jobs("SELECT COUNT(*) AS n FROM hrm_retention_policy_versions WHERE state='active'")[0].n,0,"the application seeds no category retention period");assert.equal((await S.employeeA.get("/hrm/retention")).status,403,"employees cannot access retention controls");
 assert.equal((await S.employeeA.get("/hrm")).status,403,"an employee without a linked employment period has no self-service access");
 P.a=await createPerson({user:S.employeeA,code:`TEST-A-${run}`,name:"TEST Employee A"});
 P.b=await createPerson({user:S.employeeB,code:`TEST-B-${run}`,name:"TEST Employee B",manager:S.manager.id});
 if(browserQa){
  console.log("HRM browser QA employee overview EN:",JSON.stringify(await browserQa.auditPage(S.employeeA,"/hrm",{expectedText:"HRM overview",artifactName:"p1-overview-en",formsRequired:false})));
  console.log("HRM browser QA employee overview VI:",JSON.stringify(await browserQa.auditPage(S.employeeA,"/vi/hrm",{expectedText:"Tổng quan HRM",artifactName:"p1-overview-vi",formsRequired:false})));
  console.log("HRM browser QA employee profile EN:",JSON.stringify(await browserQa.auditPage(S.employeeA,"/hrm/me",{expectedText:"Employee profile",artifactName:"p1-profile-en"})));
  console.log("HRM browser QA employee identity VI:",JSON.stringify(await browserQa.auditPage(S.employeeA,"/vi/hrm/me?section=identity",{expectedText:"Giấy tờ định danh",artifactName:"p1-identity-vi"})));
  console.log("HRM browser QA people list EN:",JSON.stringify(await browserQa.auditPage(S.hrm,"/hrm/people",{expectedText:"People",artifactName:"p1-people-en"})));
  console.log("HRM browser QA people list VI:",JSON.stringify(await browserQa.auditPage(S.hrm,"/vi/hrm/people",{expectedText:"Nhân sự",artifactName:"p1-people-vi"})));
  console.log("HRM browser QA manager people scope:",JSON.stringify(await browserQa.auditPage(S.manager,"/hrm/people",{expectedText:"People",artifactName:"p1-manager-people"})));
  console.log("HRM browser QA new employee EN:",JSON.stringify(await browserQa.auditPage(S.hrm,"/hrm/people/new",{expectedText:"Employment record",artifactName:"p1-new-person-en"})));
  console.log("HRM browser QA new employee VI:",JSON.stringify(await browserQa.auditPage(S.hrm,"/vi/hrm/people/new",{expectedText:"Tạo hồ sơ",artifactName:"p1-new-person-vi"})));
  console.log("HRM browser QA identity review EN:",JSON.stringify(await browserQa.auditPage(S.hrm,`/hrm/people/${P.a}/profile?section=identity`,{expectedText:"Identity documents",artifactName:"p1-identity-review-en"})));
  console.log("HRM browser QA work details EN:",JSON.stringify(await browserQa.auditPage(S.hrm,`/hrm/people/${P.b}`,{expectedText:"Work details",artifactName:"p1-work-details-en"})));
  console.log("HRM browser QA work details VI:",JSON.stringify(await browserQa.auditPage(S.hrm,`/vi/hrm/people/${P.b}`,{expectedText:"Thông tin công việc",artifactName:"p1-work-details-vi"})));
  console.log("HRM browser QA settings EN:",JSON.stringify(await browserQa.auditPage(S.hrm,"/hrm/settings",{expectedText:"HRM activation conditions",artifactName:"p1-settings-en"})));
  console.log("HRM browser QA settings VI:",JSON.stringify(await browserQa.auditPage(S.hrm,"/vi/hrm/settings",{expectedText:"Điều kiện mở HRM",artifactName:"p1-settings-vi"})));
  for(const [section,en,vi] of [["contact","Contact and emergency","Liên hệ và khẩn cấp"],["personal","Personal information","Thông tin cá nhân"],["dependent","Dependents","Người phụ thuộc"],["bank","Salary payment account","Tài khoản nhận lương"],["tax","Tax and insurance","Thuế và bảo hiểm"]]){
   console.log(`HRM browser QA employee ${section} EN:`,JSON.stringify(await browserQa.auditPage(S.employeeA,`/hrm/me?section=${section}`,{expectedText:en,artifactName:`p1-${section}-en`})));
   console.log(`HRM browser QA employee ${section} VI:`,JSON.stringify(await browserQa.auditPage(S.employeeA,`/vi/hrm/me?section=${section}`,{expectedText:vi,artifactName:`p1-${section}-vi`})));
  }
 }
 // A transfer needs authority on both sides, a hired source and an explicit active EmDash Employee selection.
