 jobs(`INSERT INTO applications(id,public_id,job_id,full_name,email,phone,cover_letter,consent,source,status,created_at,updated_at) VALUES(${q(transferApplication)},${q(`PUBLIC-TRANSFER-${run}`)},${q(transferJob)},'TEST Candidate Transfer','test-candidate-transfer@example.test','0900000999','TEST recruiter-only cover letter',1,'jobs','hired',${q(transferNow)},${q(transferNow)})`);
 jobs(`INSERT INTO application_notes(id,application_id,author,body,created_at) VALUES(${q(`note_transfer_${run}`)},${q(transferApplication)},'TEST recruiter','TEST private recruiter note must not enter HRM',${q(transferNow)})`);
