 const transferPreview=await S.system.get(`/hrm/transfers/${transferApplication}`);assert.equal(transferPreview.status,200);assert.ok(transferPreview.html.includes("TEST Candidate Transfer"));assert.ok(transferPreview.html.includes("TEST Operations"));assert.ok(!transferPreview.html.includes("TEST recruiter-only cover letter"));assert.ok(!transferPreview.html.includes("TEST private recruiter note"));assert.ok(transferPreview.html.includes("Choose manually — no email matching"));
 if(browserQa)await auditPair(S.system,"p2-transfer-preview",`/hrm/transfers/${transferApplication}`,`/vi/hrm/transfers/${transferApplication}`,"Transfer preview","Dữ liệu xem trước");
 assert.equal((await S.system.get(`/vi/hrm/transfers/${transferApplication}`)).status,200,"Vietnamese transfer route is available");
 const transferFields={request_key:`ats_transfer_${run}`,source_updated_at:transferNow,job_updated_at:transferNow,settings_version:2,employee_code:`TEST-TRANSFER-${run}`,employee_account_email:S.transferEmployee.email,manager_email:S.manager.email,started_on:"2026-10-15",confirm_transfer:"1"};
 const transferResult=await S.system.post(`/api/hrm/transfers/${transferApplication}`,transferFields);assert.equal(transferResult.status,303);
 assert.equal((await S.system.post(`/api/hrm/transfers/${transferApplication}`,transferFields)).status,303,"retrying the same ATS transfer command is idempotent");
