 if(browserQa)await auditPair(S.system,"p2-transfer-completed",`/hrm/transfers/${transferApplication}`,`/vi/hrm/transfers/${transferApplication}`,"Candidate transferred to HRM","Đã chuyển hồ sơ sang HRM");
 const transferredPerson=jobs(`SELECT p.user_id,p.legal_name,e.work_email,e.work_phone,e.department,e.job_title,e.legal_entity,e.location,e.status,e.started_on FROM hrm_people p JOIN hrm_employments e ON e.person_id=p.id WHERE p.id=${q(atsTransfer.person_id)}`)[0];assert.equal(transferredPerson.user_id,S.transferEmployee.id);assert.equal(transferredPerson.legal_name,"TEST Candidate Transfer");assert.equal(transferredPerson.work_email,"test-candidate-transfer@example.test");assert.equal(transferredPerson.job_title,"TEST Analyst");assert.equal(transferredPerson.department,"TEST Operations");assert.equal(transferredPerson.status,"preboarding");assert.equal(transferredPerson.started_on,"2026-10-15");
 const transferProvenance=JSON.parse(atsTransfer.transferred_fields_json);assert.ok(transferProvenance.includes("full_name→legal_name"));assert.ok(transferProvenance.includes("job.title→job_title"));assert.ok(!transferProvenance.some(field=>/resume|file|answer|note|scorecard|cover/i.test(field)));
 assert.equal(jobs(`SELECT COUNT(*) AS n FROM hrm_files WHERE person_id=${q(atsTransfer.person_id)}`)[0].n,0,"ATS files are never copied to the private HRM file store");
 const staleApplication=`app_stale_transfer_${run}`;jobs(`INSERT INTO applications(id,public_id,job_id,full_name,email,phone,consent,source,status,created_at,updated_at) VALUES(${q(staleApplication)},${q(`PUBLIC-STALE-${run}`)},${q(transferJob)},'TEST Stale Candidate','test-stale@example.test','0900000998',1,'jobs','hired',${q(transferNow)},${q(transferNow)})`);
 const stalePreview=await S.system.get(`/hrm/transfers/${staleApplication}`);assert.equal(stalePreview.status,200);jobs(`UPDATE applications SET updated_at='2026-10-14T23:59:59.000Z' WHERE id=${q(staleApplication)}`);
 const staleTransfer=await S.system.post(`/api/hrm/transfers/${staleApplication}`,{...transferFields,request_key:`ats_stale_${run}`,source_updated_at:transferNow});assert.equal(staleTransfer.status,303);assert.equal(new URL(staleTransfer.location,BASE).searchParams.get("error"),"transfer_preview_stale");assert.equal(jobs(`SELECT COUNT(*) AS n FROM hrm_ats_transfers WHERE source_application_id=${q(staleApplication)}`)[0].n,0,"a stale candidate snapshot cannot create an HRM employee");
 assert.equal((await S.system.post(`/api/admin/applications/${transferApplication}/delete`,{confirm:"1",lang:"en"})).status,303,"synthetic ATS source deletion succeeds");
 assert.equal(jobs(`SELECT COUNT(*) AS n FROM applications WHERE id=${q(transferApplication)}`)[0].n,0);assert.equal(jobs(`SELECT COUNT(*) AS n FROM hrm_people WHERE id=${q(atsTransfer.person_id)}`)[0].n,1,"ATS application removal does not delete the HRM person");assert.equal(jobs(`SELECT COUNT(*) AS n FROM hrm_ats_transfers WHERE source_application_id=${q(transferApplication)}`)[0].n,1,"ATS source removal preserves non-cascading transfer provenance");
 assert.equal((await S.system.get(`/hrm/transfers/${transferApplication}`)).status,200,"HRM transfer record remains readable after ATS source deletion");
