 const correction=jobs(`SELECT id,version,state,adjustment_of_payslip_id FROM hrm_payroll_runs WHERE adjustment_of_payslip_id=${q(oldSlip.id)}`)[0];assert.ok(correction);assert.equal(correction.state,"draft");
