 correctionNow=jobs(`SELECT id,version,state FROM hrm_payroll_runs WHERE id=${q(correction.id)}`)[0];assert.equal((await S.hrm.post("/api/hrm/payroll",{intent:"approve_run",return_to:`/hrm/payroll?run=${correction.id}`,request_key:`p4_correction_approve_${run}`,run_id:correction.id,version:correctionNow.version,reason:"TEST approval of immutable correction"})).status,303);
  correctionNow=jobs(`SELECT id,version,state FROM hrm_payroll_runs WHERE id=${q(correction.id)}`)[0];
