  const finalPartial=11000-expectedCarryover-5000;assert.equal((await S.hrm.post("/api/hrm/payroll",{...paymentFields,request_key:`p4_payment_part2_${run}`,amount_minor:String(finalPartial),payment_reference:"TEST-P4-PAYMENT-2",evidence_reference:"TEST-P4-RECONCILIATION-2"})).status,303);assert.equal(jobs(`SELECT SUM(amount_minor) AS n FROM hrm_payroll_payments WHERE payslip_id=${q(newSlip.id)}`)[0].n,finalPartial+5000);assert.equal(expectedCarryover+jobs(`SELECT SUM(amount_minor) AS n FROM hrm_payroll_payments WHERE payslip_id=${q(newSlip.id)}`)[0].n,11000);
