 runState=jobs(`SELECT id,version,state FROM hrm_payroll_runs WHERE id=${q(runRow.id)}`)[0];assert.equal((await S.hrm.post("/api/hrm/payroll",{intent:"close_run",return_to:`/hrm/payroll?run=${runRow.id}`,request_key:`p4_original_run_close_${run}`,run_id:runRow.id,version:runState.version,reason:"TEST original run is settled by the fully paid linked correction"})).status,303);assert.equal(jobs(`SELECT state FROM hrm_payroll_runs WHERE id=${q(runRow.id)}`)[0].state,"closed");
