 assert.equal((await S.payroll.post("/api/hrm/payroll",{intent:"transition_dispute",return_to:"/hrm/payroll",request_key:`p4_dispute_reinvestigate_${run}`,dispute_id:dispute.id,version:dispute.version,next_state:"investigating",body:"TEST follow-up investigated"})).status,303);dispute=jobs(`SELECT id,version,state FROM hrm_payroll_disputes WHERE id=${q(dispute.id)}`)[0];
